INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0001', 'pt', 'olá', 'hello', 'interj', NULL, NULL, 'Olá, tudo bem?', 'Hello, how are you?', '["core","saudacao"]', 1) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0002', 'pt', 'bom dia', 'good morning', 'phrase', NULL, 'until noon; after that — boa tarde', 'Bom dia! Um café, se faz favor.', 'Good morning! A coffee, please.', '["core","saudacao"]', 2) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0003', 'pt', 'boa tarde', 'good afternoon', 'phrase', NULL, 'from noon until dark', 'Boa tarde, faz favor.', 'Good afternoon, please.', '["core","saudacao"]', 3) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0004', 'pt', 'boa noite', 'good evening / good night', 'phrase', NULL, 'both a greeting and a farewell', 'Boa noite, até amanhã.', 'Good night, see you tomorrow.', '["core","saudacao"]', 4) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0005', 'pt', 'obrigado', 'thank you', 'interj', NULL, 'agrees with the SPEAKER''s gender: men say obrigado, women — obrigada', 'Muito obrigado pela ajuda.', 'Thank you very much for the help.', '["core","cortesia"]', 5) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0006', 'pt', 'de nada', 'you''re welcome', 'phrase', NULL, NULL, '— Obrigado! — De nada.', '— Thanks! — You''re welcome.', '["core","cortesia"]', 6) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0007', 'pt', 'se faz favor', 'please (request)', 'phrase', NULL, 'distinctly European Portuguese; Brazilians say por favor', 'A conta, se faz favor.', 'The bill, please.', '["core","cortesia","pt-pt"]', 7) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0008', 'pt', 'desculpe', 'excuse me / sorry', 'interj', NULL, 'formal; informal — desculpa', 'Desculpe, pode ajudar-me?', 'Excuse me, can you help me?', '["core","cortesia"]', 8) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0009', 'pt', 'com licença', 'excuse me (passing by)', 'phrase', NULL, 'when squeezing past someone, not when apologising', 'Com licença, posso passar?', 'Excuse me, may I pass?', '["core","cortesia"]', 9) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0010', 'pt', 'adeus', 'goodbye', 'interj', NULL, NULL, 'Adeus, boa viagem!', 'Goodbye, have a good trip!', '["core","saudacao"]', 10) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0011', 'pt', 'até logo', 'see you later', 'phrase', NULL, NULL, 'Até logo, vemo-nos amanhã.', 'See you later, we''ll meet tomorrow.', '["core","saudacao"]', 11) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0012', 'pt', 'sim', 'yes', 'adv', NULL, 'in speech people often repeat the verb instead: «Tens?» — «Tenho»', 'Sim, claro.', 'Yes, of course.', '["core"]', 12) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0013', 'pt', 'não', 'no; not', 'adv', NULL, NULL, 'Não, obrigado.', 'No, thank you.', '["core"]', 13) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0014', 'pt', 'não percebo', 'I don''t understand', 'phrase', NULL, 'key pt-PT marker: perceber = to understand; Brazilian entender sounds foreign here', 'Desculpe, não percebo.', 'Sorry, I don''t understand.', '["core","sobrevivencia","pt-pt"]', 14) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0015', 'pt', 'não falo bem português', 'I don''t speak Portuguese well', 'phrase', NULL, 'the phrase that makes people slow down for you', 'Desculpe, não falo bem português.', 'Sorry, I don''t speak Portuguese well.', '["core","sobrevivencia"]', 15) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0016', 'pt', 'pode repetir, se faz favor?', 'can you repeat, please?', 'phrase', NULL, NULL, 'Pode repetir, se faz favor? Não percebi.', 'Can you repeat, please? I didn''t understand.', '["core","sobrevivencia"]', 16) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
