INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0019', 'pt', 'a conta', 'the bill', 'noun', 'f', 'in a café you ask: «A conta, se faz favor»', 'A conta, se faz favor.', 'The bill, please.', '["core","cafe"]', 19) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
