INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq) VALUES ('pt0028', 'pt', 'ser', 'to be (permanent)', 'verb', NULL, 'permanent traits: sou russo. Temporary states — estar', 'Eu sou russo, moro na Madeira.', 'I''m Russian, I live in Madeira.', '["core","verbo","irregular"]', 28) ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq;
